/* Fictional browser demo only; PHP enforces the real authorization. */
const classBaseDetail=personDetail;
personDetail=function(id){classBaseDetail(id);if(!organizer())return;const p=state.people.find(p=>p.id===id);document.querySelector('#modalBody').insertAdjacentHTML('beforeend','<section class="panel"><h3>卒業時のクラスを確認・修正</h3><p>現在：'+esc(R.classLabel(p.class))+'</p><form id="correctClassForm">'+'<input type="hidden" name="id" value="'+id+'"><input type="hidden" name="revision" value="'+p.revision+'">'+select('class','確認したクラス',[['','クラスを選択'],...Array.from({length:10},(_,i)=>[i+1,'3年'+(i+1)+'組'])],'')+field('reason','確認・修正理由')+'<p class="error-text" role="alert"></p><button class="btn">クラスを修正して記録</button></form></section>');};
const classBaseAdmin=adminPage;
adminPage=function(){return classBaseAdmin().replace('<h3>参加者を確認</h3>','<h3>参加者を確認</h3><p>クラス未確認：'+state.people.filter(p=>p.class===0).length+'件</p>');};
document.addEventListener('submit',ev=>{const f=ev.target;if(f.id!=='correctClassForm')return;ev.preventDefault();ev.stopImmediatePropagation();try{const d=Object.fromEntries(new FormData(f));if(!organizer())throw new Error('幹事権限が必要です。');change(s=>R.correctClass(s,current(),d.id,d.class,d.revision,d.reason));document.querySelector('#modal').close();route();toast('クラスを修正し、変更履歴を保存しました');}catch(e){f.querySelector('.error-text').textContent=e.message;}},true);
